import { type Knob as KnobController, type KnobOptions, createKnob } from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createSignal, merge, untrack } from "solid-js";

import { t } from "./theme.ts" with { type: "cssints" };

export interface KnobProps extends Omit<KnobOptions, "id" | "labels"> {
  /** The knob's visible name, which is also its accessible name. */
  readonly label: string;
  /** The dial's diameter in CSS. @default "6rem" */
  readonly size?: string | undefined;
  /** The primitive, once: a page that reads the value as well as shows it. */
  readonly onReady?: (knob: KnobController) => void;
  readonly class?: string | undefined;
}

const DEFAULT_SIZE = "6rem";
/** The arc sweeps three quarters of a turn, from the bottom-left to the bottom-right of the dial. */
const SWEEP = 0.75;
const START_DEGREES = -135;

const rootClass = css.cn(
  css.display("grid"),
  css.justifyItems("center"),
  css.gap(t.space._1),
  css.color(t.color.text),
  css.fontSize(t.font.size),
);

const labelClass = css.cn(
  css.fontSize(t.font.sizeSm),
  css.fontWeight("500"),
  css.color(t.color.muted),
);

// The dial is the control: the primitive's role, tab stop and aria-* sit on this box, and the ring is drawn outside its
// rounded edge. `touch-action` and `user-select` are the one thing the spin and the slides need from CSS (the primitive
// carries none): a press on a touch dial must turn it instead of scrolling the page, and a mouse drag must not select text.
const dialClass = css.cn(
  css.position("relative"),
  css.display("grid"),
  css.placeItems("center"),
  css.boxSizing("border-box"),
  css.borderRadius("999px"),
  css.cursor("grab"),
  css.touchAction("none"),
  css.userSelect("none"),
  css.outline("none"),
  css.group("knob-dial"),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
  css.hover(css.bg(t.color.buttonBackground)),
  css.attr("data-dragging", "true")(
    css.cursor("grabbing"),
    css.bg(t.color.buttonBackgroundPressed),
  ),
);

const svgClass = css.cn(
  css.position("absolute"),
  css.inset("0"),
  css.display("block"),
  css.width("100%"),
  css.height("100%"),
  css.overflow("visible"),
  css.pointerEvents("none"),
);

const arcClass = css.cn(css.fill("none"), css.strokeWidth("8"), css.strokeLinecap("round"));

// The track is the dial's whole sweep, the value arc grows from its start; both are drawn with `pathLength=100`, so the two
// numbers of the dash are a percentage of the sweep and the skin needs no circumference. The arc follows a key or a wheel
// for a reader who allows motion, and snaps while the pointer drags it, so the paint never lags the hand.
const trackClass = css.cn(arcClass, css.stroke(t.color.border));

const valueClass = css.cn(
  arcClass,
  css.stroke(t.color.highlight),
  css.media("(prefers-reduced-motion: no-preference)")(
    css.transition("stroke-dasharray 140ms ease-out"),
  ),
  css.within(css.attr("data-dragging", "true"), "knob-dial")(css.transition("none")),
);

const pointerClass = css.cn(
  css.stroke(t.color.text),
  css.strokeWidth("3"),
  css.strokeLinecap("round"),
  css.media("(prefers-reduced-motion: no-preference)")(css.transition("transform 140ms ease-out")),
  css.within(css.attr("data-dragging", "true"), "knob-dial")(css.transition("none")),
);

// The readout is decoration: the primitive's `aria-valuetext` already says the value, and the live region repeats it. It is
// sized from the dial, so one `size` prop moves the figure with the circle; the tabular figures keep it from shifting.
const readoutClass = css.cn(
  css.pointerEvents("none"),
  css.fontWeight("600"),
  css.fontVariantNumeric("tabular-nums"),
  css.lineHeight(1),
  css.color(t.color.text),
);

// The live value: in the page and visually hidden, never `hidden` (a hidden live region is not announced).
const liveClass = css.cn(
  css.position("absolute"),
  css.width("1px"),
  css.height("1px"),
  css.overflow("hidden"),
  css.clipPath("inset(50%)"),
  css.whiteSpace("nowrap"),
);

/**
 * A knob, styled: `createKnob` owns the value, the bounds and the step, the spin and the two slides, the wheel, the arrows,
 * PageUp/PageDown, Home/End, and every `aria-*` the dial announces. The skin owns the look: the dial and its size, the
 * three-quarter arc with its track tone and its value tone, the pointer at the value, the visible readout taken from the
 * primitive's own `aria-valuetext` (so `format` is the one place the text is made), the label above, the focus ring, and the
 * reduced-motion rule.
 *
 * Nothing about the value lives here: the arc, the pointer and the readout all read `percentOf` and the announced value, so a
 * key, a drag and a host's controlled write paint the same picture. `value` makes it controlled; without it the knob owns the
 * value, and `onValueChange` is a request the host may ignore. There is no `disabled` in the primitive, so there is no
 * disabled look either.
 */
export const Knob = (props: KnobProps): JSX.Element => {
  const knob = createKnob({
    get min() {
      return props.min;
    },
    get max() {
      return props.max;
    },
    get step() {
      return props.step;
    },
    get value() {
      return props.value;
    },
    defaultValue: props.defaultValue,
    get wrap() {
      return props.wrap;
    },
    get gesture() {
      return props.gesture;
    },
    get format() {
      return props.format;
    },
    labels: { knob: props.label },
    get onValueChange() {
      return props.onValueChange;
    },
  });
  untrack(() => props.onReady)?.(knob);

  // The primitive does not announce a drag: the skin tracks it only to drop the arc's transition while the hand is on it.
  const [dragging, setDragging] = createSignal(false);

  const down = (event: PointerEvent): void => {
    knob.knobProps.onPointerDown(event);
    setDragging(true);
  };
  const up = (event: PointerEvent): void => {
    knob.knobProps.onPointerUp(event);
    setDragging(false);
  };
  const cancel = (event: PointerEvent): void => {
    knob.knobProps.onPointerCancel(event);
    setDragging(false);
  };

  const size = (): string => props.size ?? DEFAULT_SIZE;
  const turn = (): number => knob.percentOf(knob.value());
  const angle = (): number => Number((START_DEGREES + 360 * SWEEP * turn()).toFixed(3));

  const dial = merge(knob.knobProps, {
    "data-part": "knob-dial",
    get "data-dragging"() {
      return dragging() ? "true" : "false";
    },
    get class() {
      return css.cn(dialClass, props.class);
    },
    onPointerDown: down,
    onPointerUp: up,
    onPointerCancel: cancel,
    onLostPointerCapture: () => setDragging(false),
  });

  return (
    <div data-part="knob" class={rootClass}>
      <span class={labelClass}>{props.label}</span>
      <div {...dial} style={{ width: size(), height: size(), "font-size": `calc(${size()} / 5)` }}>
        <svg aria-hidden="true" class={svgClass} viewBox="0 0 100 100">
          <circle
            data-part="knob-track"
            class={trackClass}
            cx="50"
            cy="50"
            r="43"
            pathLength="100"
            transform="rotate(135 50 50)"
            stroke-dasharray={`${100 * SWEEP} 100`}
          />
          <circle
            data-part="knob-arc"
            class={valueClass}
            cx="50"
            cy="50"
            r="43"
            pathLength="100"
            transform="rotate(135 50 50)"
            stroke-dasharray={`${100 * SWEEP * turn()} 100`}
          />
          <line
            data-part="knob-pointer"
            class={pointerClass}
            x1="50"
            y1="15"
            x2="50"
            y2="22"
            transform={`rotate(${angle()} 50 50)`}
          />
        </svg>
        <span data-part="knob-readout" aria-hidden="true" class={readoutClass}>
          {knob.knobProps["aria-valuetext"]}
        </span>
      </div>
      <span {...knob.valueProps} data-part="knob-value" class={liveClass}>
        {knob.value()}
      </span>
    </div>
  );
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import { render } from "@solidjs/web";
import type { JSX } from "@solidjs/web";

import { Knob } from "./knob.tsx";

/**
 * The starter in ordinary use: a volume from 0 to 100 with a percentage, and a pan from -50 to 50 whose centre is
 * its own word. The sentence under the dials is the whole contract, so a reader needs no source to try them.
 */
export const KnobExample = (props: { readonly class?: string | undefined }): JSX.Element => (
  <div class={props.class === undefined ? "demo-column" : `demo-column ${props.class}`}>
    <div class="demo-row" style={{ "align-items": "flex-start", gap: "2rem" }}>
      <Knob label="Volume" defaultValue={65} format={(value) => `${value}%`} />
      <Knob
        label="Pan"
        min={-50}
        max={50}
        step={5}
        defaultValue={0}
        format={(value) => (value === 0 ? "Centre" : value < 0 ? `${-value} L` : `${value} R`)}
      />
    </div>
    <p class="demo-text">
      Drag a dial to turn it — around its centre or straight up and down; focus it and the arrow
      keys step, Page Up and Page Down jump ten steps, and Home and End go to the ends.
    </p>
  </div>
);

/** What a mounted demo hands the test: where it lives and a teardown. */
export interface MountedKnob {
  readonly root: HTMLElement;
  readonly dispose: () => void;
}

/** Mounts the styled knobs the way the docs page does. */
export const mountKnob = (): MountedKnob => {
  const root = document.createElement("div");
  document.body.append(root);
  const dispose = render(() => <KnobExample />, root);
  return {
    root,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

import { afterEach, describe, expect, it } from "vite-plus/test";
import { userEvent } from "vite-plus/test/browser";

import { type MountedKnob, mountKnob } from "./knob.fixture";

// @cssints/headless checks `createKnob` on a real dial in test/knob.browser.test.tsx: no APG pattern and no ARIA dial role
// exist, so that file is the primitive's oracle. This file is the skin's: it mounts the starter in a real Chromium and reads
// the same announced state, then drives the keys and the pointer the way a reader does. The pan dial's step of 5 is not a
// detent the skin adds: the primitive has none, and the host's step is what makes 0 easy to reach again.

/** Solid applies setters on the next flush; a frame lets the paint settle before a computed style is read. */
const frame = (): Promise<void> =>
  new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => resolve())));

/** Polls until `done` holds, so a transition is waited for rather than assumed. */
const waitFor = async (done: () => boolean, limit = 2000): Promise<void> => {
  const start = performance.now();
  while (!done()) {
    if (performance.now() - start > limit) {
      throw new Error("waitFor timed out");
    }
    await frame();
  }
};

const live: MountedKnob[] = [];

const mounted = (): MountedKnob => {
  const instance = mountKnob();
  live.push(instance);
  return instance;
};

afterEach(() => {
  for (const instance of live.splice(0)) {
    instance.dispose();
  }
});

const dials = (root: ParentNode): HTMLElement[] => [
  ...root.querySelectorAll<HTMLElement>('[data-part="knob-dial"]'),
];

const dial = (root: ParentNode, index = 0): HTMLElement => {
  const element = dials(root)[index];
  if (element === undefined) {
    throw new Error(`knob: no dial ${index}`);
  }
  return element;
};

const readout = (root: ParentNode, index = 0): HTMLElement => {
  const element = root.querySelectorAll<HTMLElement>('[data-part="knob-readout"]')[index];
  if (element === undefined) {
    throw new Error(`knob: no readout ${index}`);
  }
  return element;
};

const arc = (root: ParentNode, part: string, index = 0): SVGElement => {
  const element = root.querySelectorAll<SVGElement>(`[data-part="${part}"]`)[index];
  if (element === undefined) {
    throw new Error(`knob: no ${part} ${index}`);
  }
  return element;
};

const value = (element: HTMLElement): number => Number(element.getAttribute("aria-valuenow"));

const press = async (target: HTMLElement, key: string): Promise<void> => {
  target.dispatchEvent(new KeyboardEvent("keydown", { key, bubbles: true, cancelable: true }));
  await frame();
};

/** The pointer of a drag, as the primitive's handlers receive it. */
const pointer = (
  element: HTMLElement,
  type: string,
  position: { readonly x: number; readonly y: number },
  buttons: number,
): void => {
  element.dispatchEvent(
    new PointerEvent(type, {
      bubbles: true,
      cancelable: true,
      composed: true,
      pointerId: 1,
      pointerType: "mouse",
      isPrimary: true,
      button: 0,
      buttons,
      clientX: position.x,
      clientY: position.y,
    }),
  );
};

const centre = (element: HTMLElement): { readonly x: number; readonly y: number } => {
  const box = element.getBoundingClientRect();
  return { x: box.left + box.width / 2, y: box.top + box.height / 2 };
};

describe("Knob", () => {
  it("is a named role=slider with its value in the middle and a polite live value", async () => {
    const { root } = mounted();
    await frame();

    const volume = dial(root);
    expect(volume.getAttribute("role")).toBe("slider");
    expect(volume.getAttribute("aria-label")).toBe("Volume");
    expect(volume.tabIndex).toBe(0);
    expect(volume.getAttribute("aria-valuemin")).toBe("0");
    expect(volume.getAttribute("aria-valuemax")).toBe("100");
    expect(volume.getAttribute("aria-valuenow")).toBe("65");
    expect(volume.getAttribute("aria-valuetext")).toBe("65%");
    expect(readout(root).textContent).toBe("65%");

    // the live region is rendered and visually hidden, never `hidden`
    const status = root.querySelector('[data-part="knob-value"]');
    expect(status?.getAttribute("role")).toBe("status");
    expect(status?.getAttribute("aria-live")).toBe("polite");
    expect(status?.getAttribute("hidden")).toBeNull();
    expect(getComputedStyle(status as HTMLElement).clipPath).toBe("inset(50%)");

    // the second dial has its own range, its own word for the centre, and no % formatter
    const pan = dials(root)[1];
    if (pan === undefined) {
      throw new Error("knob: no pan dial");
    }
    expect(pan.getAttribute("aria-label")).toBe("Pan");
    expect(pan.getAttribute("aria-valuemin")).toBe("-50");
    expect(pan.getAttribute("aria-valuemax")).toBe("50");
    expect(pan.getAttribute("aria-valuenow")).toBe("0");
    expect(pan.getAttribute("aria-valuetext")).toBe("Centre");
  });

  it("paints the track and the value arc from the value, with the pointer at the same angle", async () => {
    const { root } = mounted();
    await frame();

    // a 270° sweep over pathLength=100: the track is 75 long, the value arc 75 × 65%
    expect(arc(root, "knob-track").getAttribute("stroke-dasharray")).toBe("75 100");
    expect(arc(root, "knob-arc").getAttribute("stroke-dasharray")).toBe("48.75 100");
    expect(arc(root, "knob-pointer").getAttribute("transform")).toBe("rotate(40.5 50 50)");

    // the two tones are different tokens, so the value arc reads against its track
    const track = getComputedStyle(arc(root, "knob-track")).stroke;
    const grew = getComputedStyle(arc(root, "knob-arc")).stroke;
    expect(grew).not.toBe(track);

    await press(dial(root), "ArrowUp");
    expect(arc(root, "knob-arc").getAttribute("stroke-dasharray")).toBe("49.5 100");
    expect(arc(root, "knob-pointer").getAttribute("transform")).toBe("rotate(43.2 50 50)");
  });

  it("steps with the arrows, jumps with PageUp/PageDown and Home/End, and clamps", async () => {
    const { root } = mounted();
    await frame();
    const volume = dial(root);

    await press(volume, "ArrowUp");
    expect(value(volume)).toBe(66);
    expect(volume.getAttribute("aria-valuetext")).toBe("66%");
    expect(readout(root).textContent).toBe("66%");

    await press(volume, "ArrowRight");
    await press(volume, "ArrowDown");
    await press(volume, "ArrowLeft");
    expect(value(volume)).toBe(65);
    // the primitive has no coarse step of its own: PageUp/PageDown are the ten-step jump, and Shift stays a plain step
    await press(volume, "ArrowUp");
    expect(value(volume)).toBe(66);

    await press(volume, "PageUp");
    expect(value(volume)).toBe(76);
    await press(volume, "PageDown");
    expect(value(volume)).toBe(66);
    await press(volume, "End");
    expect(value(volume)).toBe(100);
    await press(volume, "ArrowUp");
    expect(value(volume)).toBe(100);
    await press(volume, "Home");
    expect(value(volume)).toBe(0);
    await press(volume, "ArrowDown");
    expect(value(volume)).toBe(0);
  });

  it("turns by a drag and stops when the pointer is up", async () => {
    const { root } = mounted();
    await frame();
    const volume = dial(root);
    const box = volume.getBoundingClientRect();
    const start = centre(volume);

    // a straight 40 px slide down the dial's middle: the right half turns clockwise, so +20 of 100
    pointer(volume, "pointerdown", { x: start.x, y: box.top + 10 }, 1);
    pointer(volume, "pointermove", { x: start.x, y: box.top + 50 }, 1);
    await frame();
    expect(value(volume)).toBe(85);
    expect(volume.getAttribute("data-dragging")).toBe("true");
    // the arc snaps to the hand instead of easing after it
    await waitFor(() => getComputedStyle(arc(root, "knob-arc")).transitionDuration === "0s");

    pointer(volume, "pointerup", { x: start.x, y: box.top + 50 }, 0);
    await frame();
    expect(volume.getAttribute("data-dragging")).toBe("false");
    await waitFor(() => getComputedStyle(arc(root, "knob-arc")).transitionDuration !== "0s");

    // the pointer keeps moving, but the drag is over: nothing changes
    pointer(volume, "pointermove", { x: start.x, y: box.top + 90 }, 0);
    await frame();
    expect(value(volume)).toBe(85);

    // and the end of the range is the end: a long slide clamps there
    pointer(volume, "pointerdown", { x: start.x, y: box.top + 10 }, 1);
    pointer(volume, "pointermove", { x: start.x, y: box.top + 400 }, 1);
    pointer(volume, "pointerup", { x: start.x, y: box.top + 400 }, 0);
    await frame();
    expect(value(volume)).toBe(100);
  });

  it("reaches the range with the pan dial's own step and word for the centre", async () => {
    const { root } = mounted();
    await frame();
    const pan = dial(root, 1);

    await press(pan, "ArrowUp");
    expect(value(pan)).toBe(5);
    expect(pan.getAttribute("aria-valuetext")).toBe("5 R");
    await press(pan, "ArrowUp");
    await press(pan, "ArrowDown");
    expect(value(pan)).toBe(5);
    await press(pan, "PageUp");
    expect(value(pan)).toBe(50);
    expect(pan.getAttribute("aria-valuetext")).toBe("50 R");
    await press(pan, "Home");
    expect(value(pan)).toBe(-50);
    expect(pan.getAttribute("aria-valuetext")).toBe("50 L");
  });

  it("draws the focus ring when Tab reaches the dial", async () => {
    const { root } = mounted();
    await frame();
    const volume = dial(root);

    (document.activeElement as HTMLElement | null)?.blur();
    await userEvent.keyboard("{Tab}");
    await frame();
    expect(document.activeElement).toBe(volume);
    const style = getComputedStyle(volume);
    expect(style.outlineStyle).toBe("solid");
    expect(parseFloat(style.outlineWidth)).toBeGreaterThanOrEqual(2);
    expect(root.contains(document.activeElement)).toBe(true);
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
